package com.campusconnect.rag; import com.campusconnect.user.User; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="campus_documents") public class CampusDocument { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=240) private String title; @Column(nullable=false,length=500) private String originalName; @ManyToOne(optional=false) private User uploadedBy; @Column(nullable=false,updatable=false) private Instant uploadedAt=Instant.now(); protected CampusDocument(){} public CampusDocument(String t,String n,User u){title=t;originalName=n;uploadedBy=u;} public Long getId(){return id;} public String getTitle(){return title;} public String getOriginalName(){return originalName;} public User getUploadedBy(){return uploadedBy;} public Instant getUploadedAt(){return uploadedAt;} }
